    def fmt(h):
        return str(len(h)) + '\n' + ' '.join(map(str, h))
    tests = [fmt([0, 0]), fmt([5, 5]), fmt([1, 10000]), fmt([10000, 1]), fmt([3, 1, 2, 4, 5]),
             fmt(list(range(1, 11))), fmt(list(range(10, 0, -1))), fmt([0, 7, 0]), fmt([4, 0, 0, 0, 4])]
    for n in (2, 3, 4, 6, 8, 10, 12, 15):
        for _ in range(2):
            tests.append(fmt([rng.randint(0, 10) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 10**4) for _ in range(100000)]))
    tests.append(fmt([10**4] * 100000))
    tests.append(fmt([i // 10 + 1 for i in range(100000)]))
    tests.append(fmt([rng.randint(9000, 10**4) if i in (0, 99999) else rng.randint(0, 5000) for i in range(100000)]))
    return tests

